func countSuitable(x int64) int64 {
	if x < 3 {
		return 0
	}
	odds := (x - 1) / 2 // odds >=3
	mult4 := int64(0)
	if x >= 8 {
		mult4 = x/4 - 1
	}
	return odds + mult4
